/**
 * `DeployableEntity` (kind "documentModel", built by a file-reader factory) →
 * one `elementum_<excel|json|text>_file_reader` resource block. Mirrors
 * `skill/to-tf.ts`'s shape for a single-resource own-file kind.
 */
import { EntityTfError } from "../../engine/entity.js";
import { appScopedResourceLabel, expr, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { APP_RESOURCE_TYPE } from "../app/module.js";
import { FILE_READER_SUB_TYPE_BY_TYPE_KEY } from "./types.js";
function serializeStructureField(f) {
    switch (f.type) {
        case "text":
            return { text: { name: f.name } };
        case "number":
            return { number: { name: f.name } };
        case "decimal":
            return { decimal: { name: f.name } };
        case "boolean":
            return { bool: { name: f.name } };
        case "date":
            return { date: { name: f.name, format: f.format } };
        case "datetime":
            return { datetime: { name: f.name, format: f.format } };
        case "object": {
            // ei's own export omits `properties` entirely for an object with no
            // discovered sub-fields (e.g. a nested array-of-objects item type ei
            // couldn't further introspect) rather than emitting an empty array —
            // always including it here planned a spurious in-place update on
            // every build (live-confirmed on purchaseorder/eu-sanofi's
            // "New file reader"'s `to_PurchaseOrderItem` array field).
            const properties = f.properties.map(serializeStructureField);
            return { object: { name: f.name, ...(properties.length > 0 ? { properties } : {}) } };
        }
        case "array":
            return { array: { name: f.name, arrayType: serializeStructureField(f.itemType) } };
    }
}
function aiFieldToTf(f) {
    return {
        name: f.name,
        description: f.description,
        type: f.type,
        ...(f.required !== undefined ? { required: f.required } : {}),
    };
}
function excelFieldToTf(f) {
    const location = f.location;
    return {
        name: f.name,
        type: f.type,
        location: { sheet: location.sheet, row: location.row, column: location.column },
        ...(f.include !== undefined ? { include: f.include } : {}),
        ...(f.required !== undefined ? { required: f.required } : {}),
    };
}
export function fileReaderToTf(entity, ctx) {
    if (entity.kind !== "documentModel") {
        throw new EntityTfError(`fileReaderToTf expects kind "documentModel"; got "${entity.kind}" (refName "${entity.refName}")`);
    }
    const payload = entity.payload;
    if (payload === null || typeof payload !== "object") {
        throw new EntityTfError(`file reader "${entity.refName}" has no payload — was it built with a file-reader factory?`);
    }
    const subType = FILE_READER_SUB_TYPE_BY_TYPE_KEY.get(payload.type);
    if (subType === undefined || subType.implemented !== true) {
        throw new EntityTfError(`file reader "${entity.refName}": type "${payload.type}" does not build on the terraform path yet`);
    }
    const tfLabel = appScopedResourceLabel(ctx.appTfLabel, tsLabelToTfLabel(entity.refName));
    const attrs = {
        app_id: expr.resourceAttr(APP_RESOURCE_TYPE, ctx.appTfLabel, ["id"]),
        name: payload.name,
    };
    if (payload.type === "excel") {
        attrs.first_row_is_header = payload.firstRowIsHeader;
        attrs.fields = payload.fields.map(excelFieldToTf);
        if (payload.documentContent !== undefined)
            attrs.document_content = payload.documentContent;
        if (payload.documentName !== undefined)
            attrs.document_name = payload.documentName;
        if (payload.fileType !== undefined)
            attrs.file_type = payload.fileType;
    }
    else if (payload.type === "json") {
        attrs.structure = expr.jsonencode({ properties: payload.structure.map(serializeStructureField) });
    }
    else if (payload.type === "xml") {
        attrs.values = expr.jsonencode({ properties: payload.structure.map(serializeStructureField) });
    }
    else if (payload.type === "ai") {
        attrs.instructions = payload.instructions;
        attrs.fields = payload.fields.map(aiFieldToTf);
    }
    // text: name only, already set above.
    return { blocks: [{ kind: "resource", type: subType.resourceType, label: tfLabel, attrs }] };
}
